Sequences vs Iterables:
fun main() {
    val data = (1..100).toList()

    // Eager (collections) — creates intermediate lists
    val eager = data
        .filter { println("filter $it"); it % 2 == 0 }
        .map { println("map $it"); it * 2 }
        .take(3)
    println("Eager result: $eager")

    // Lazy (sequences) — one element at a time
    val lazy_result = data.asSequence()
        .filter { println("seq filter $it"); it % 2 == 0 }
        .map { println("seq map $it"); it * 2 }
        .take(3)
        .toList()
    println("Lazy result: $lazy_result")

    // Infinite sequence
    val fib = sequence {
        var a = 0L; var b = 1L
        while (true) {
            yield(a)
            val tmp = a + b
            a = b; b = tmp
        }
    }
    println(fib.take(10).toList())

    // generateSequence
    val powers = generateSequence(1) { it * 2 }
    println(powers.take(10).toList())

    // When to use Sequences:
    // - Multiple transformations on large collections
    // - Infinite or very large data sets
    // - Early termination (take, first)
    // When to use Collections:
    // - Small collections
    // - Need indexed access
    // - Few operations

