Dispatchers & Threading:
import kotlinx.coroutines.*

fun main() = runBlocking {
    // Default dispatcher (CPU-bound)
    launch(Dispatchers.Default) {
        println("Default: ${Thread.currentThread().name}")
        // CPU-intensive computation
        fibonacci(40)
    }

    // IO dispatcher (I/O-bound)
    launch(Dispatchers.IO) {
        println("IO: ${Thread.currentThread().name}")
        // File/network operations
        delay(100)
    }

    // Unconfined — runs in current thread
    launch(Dispatchers.Unconfined) {
        println("Unconfined before: ${Thread.currentThread().name}")
        delay(10)
        println("Unconfined after: ${Thread.currentThread().name}")
    }

    // Switching dispatchers mid-coroutine
    val result = withContext(Dispatchers.Default) {
        // CPU work
        42
    }

    // Custom dispatcher
    val myDispatcher = newSingleThreadContext("MyThread")
    launch(myDispatcher) {
        println("Custom: ${Thread.currentThread().name}")
    }
    myDispatcher.close()

    // Limited parallelism
    val limited = newFixedThreadPoolContext(2, "Limited")

    println("Done")
}

fun fibonacci(n: Int): Long {
    var a = 0L; var b = 1L
    for (i in 2..n) { val tmp = a + b; a = b; b = tmp }
    return b
}

