Flow Operators Deep:
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

suspend fun main() {
    val flow = (1..5).asFlow()

    flow.filter { it % 2 == 0 }
        .map { "Item: $it" }
        .collect { println(it) }

    // Debounce
    flowOf(1, 2, 3).debounce(100)

    // Buffer for async
    (1..10).asFlow()
        .onEach { delay(100) }
        .buffer(10)
        .collect { println("Got $it") }

    // Combine
    val nums = (1..3).asFlow()
    val strs = flowOf("A", "B", "C")
    nums.combine(strs) { n, s -> "$n$s" }
        .collect { println(it) }

    // Error handling
    flow { emit(1); emit(2); throw RuntimeException("Oops") }
        .catch { e -> emit(-1) }
        .retry(2)
        .collect { println(it) }

    // flatMapLatest
    (1..3).asFlow()
        .onEach { delay(100) }
        .flatMapLatest { flow { emit(it); delay(200); emit(it * 10) } }
        .collect { println(it) }
}

