Inline Functions & Performance:
// Inline function — body is copied to call site
inline fun <T> measureTime(block: () -> T): Pair<T, Long> {
    val start = System.nanoTime()
    val result = block()
    val duration = (System.nanoTime() - start) / 1_000_000
    return result to duration
}

// crossinline: can't use return in the lambda
inline fun runOnUi(crossinline action: () -> Unit) {
    // In a Runnable, return wouldn't work without crossinline
    object : Runnable {
        override fun run() = action()
    }.run()
}

// noinline: keep lambda as object
inline fun <T, R> transform(
    value: T,
    transformer: (T) -> R,  // inlined
    noinline fallback: (T) -> R  // kept as function reference
): R {
    return transformer(value)
}

fun main() {
    val (result, ms) = measureTime {
        Thread.sleep(50)
        42
    }
    println("Got $result in ${ms}ms")

    runOnUi {
        println("Running on UI")
        // return  // would not work without crossinline
    }

    // noinline: can use as function reference
    val ref: (Int) -> Int = { it * 2 }
    println(transform(5, { it + 1 }, ref))
}

