import io.mockk.*

class UserRepo {
    fun find(id: Int): String? = null
    suspend fun save(name: String): Int = 0
}

class Greeter(private val repo: UserRepo) {
    fun greet(id: Int): String {
        val name = repo.find(id)
        return if (name != null) "Hello $name" else "Unknown"
    }
    suspend fun create(name: String): String {
        val id = repo.save(name)
        return "Created id=$id"
    }
}

fun main() {
    // Create mock
    val repo = mockk<UserRepo>()

    // Stub
    every { repo.find(1) } returns "Alice"
    every { repo.find(any()) } returns null

    val greeter = Greeter(repo)
    println(greeter.greet(1))  // Hello Alice

    // Verify
    verify { repo.find(1) }

    // Coroutine mock
    coEvery { repo.save("Bob") } coReturns 42

    // Slot capture
    val slot = slot<Int>()
    every { repo.find(capture(slot)) } returns "captured"
    greeter.greet(99)
    println(slot.captured)  // 99

    // Relaxed mock (returns defaults)
    val relaxed = mockk<UserRepo>(relaxed = true)
    println(relaxed.find(5))  // null

    confirmVerified(repo)
}

