data class User(var name: String = "", var age: Int = 0, var email: String = "")

fun main() {
    // apply — configure object, return object
    val user = User().apply {
        name = "Alice"
        age = 30
        email = "alice@example.com"
    }

    // let — transform, return result
    val greeting = user.name.let { name ->
        "Hello, $name!"
    }
    println(greeting)

    // let with null check
    val nullableName: String? = user.name
    nullableName?.let { println("Name is $it") }

    // run — compute with context, return result
    val summary = user.run {
        "${this.name} (${this.age})"
    }

    // also — perform side effect, return original
    user.also { println("Created user: $it") }

    // with — non-extension version of run
    with(user) {
        println("Inside with: $name")
    }

    // Chaining
    val result = User().apply {
        name = "Bob"
    }.let {
        it.name.uppercase()
    }
    println(result)  // BOB
}

